from math import gcd

def e(n: int, a: int, b: int) -> int:
    return (a * b) % n

def t_order(n: int, c: int) -> int:
    c %= n
    return n // gcd(c, n) if c else 1

def mov_recover(n: int, g: int, X: int, bound: int) -> int:
    target, base = e(n, X, g), e(n, g, g)
    for x in range(bound):
        if (base * x) % n == target:   # e(g,g)^x as exponent base*x
            return x
    raise ValueError('no dlog in range')

if __name__ == '__main__':
    n, g = 101, 1
    bound = t_order(n, e(n, g, g))      # = 101 here (faithful reduction)
    for secret in [2, 37, 73, 100]:
        X = (secret * g) % n
        print('true', secret, '-> recovered', mov_recover(n, g, X, bound))

