from math import gcd

def e(n: int, a: int, b: int) -> int:
    return (a * b) % n

def order_in_target(n: int, c: int) -> int:
    c %= n
    return n // gcd(c, n) if c else 1

def mov_recover(n: int, g: int, X: int) -> int:
    h: int = e(n, g, g)
    u: int = e(n, X, g)            # u = h^x as exponent: h_exp * x mod n
    m: int = order_in_target(n, h)
    for x in range(m):
        if (h * x) % n == u:
            return x
    raise ValueError('no discrete logarithm in range')
